import { type OsmPlace, queryNewcastlePlaces } from "../../integrations/overpass";
import type { Job } from "../../jobs";
import {
  createStaysRepo,
  type HotelDocument,
  type PlaceholderBookingLink,
  type StaysRepo,
  type VenueDocument,
} from "./repo";

/** The OSM data moves slowly. Once a day is plenty and kind to the public Overpass server. */
export const REFRESH_INTERVAL_MS = 24 * 60 * 60 * 1000;

/** example.com is reserved, so this link can never reach a real booking page. */
export const PLACEHOLDER_BOOKING_BASE = "https://example.com/kip-placeholder-booking/";

export function placeholderBookingLink(osmId: string): PlaceholderBookingLink {
  return {
    url: `${PLACEHOLDER_BOOKING_BASE}${osmId}`,
    placeholder: true,
    label: "Placeholder booking link, not a real booking",
  };
}

function base(place: OsmPlace, now: Date) {
  return {
    _id: place.id,
    name: place.name || null,
    location: {
      type: "Point" as const,
      coordinates: [place.longitude, place.latitude] as [number, number],
    },
    category: place.tags.tourism ?? place.tags.amenity ?? "",
    tags: place.tags,
    updatedAt: now,
  };
}

export type StaysImport = { hotels: HotelDocument[]; venues: VenueDocument[] };

/** Splits OSM places into hotels and venues (nightlife and sights). Stations are not stored. */
export function toDocuments(places: readonly OsmPlace[], now: Date): StaysImport {
  const hotels: HotelDocument[] = [];
  const venues: VenueDocument[] = [];
  for (const place of places) {
    if (place.kind === "hotel") {
      hotels.push({ ...base(place, now), bookingLink: placeholderBookingLink(place.id) });
    } else if (place.kind === "nightlife" || place.kind === "sight") {
      venues.push({ ...base(place, now), venueKind: place.kind });
    }
  }
  return { hotels, venues };
}

type ImportDeps = {
  repo: StaysRepo;
  fetchPlaces?: () => Promise<OsmPlace[]>;
  now?: Date;
};

/** Fetches Newcastle from Overpass once and upserts it. Safe to repeat. */
export async function importNewcastlePlaces(deps: ImportDeps): Promise<StaysImport> {
  const now = deps.now ?? new Date();
  const places = await (deps.fetchPlaces ?? (() => queryNewcastlePlaces()))();
  const docs = toDocuments(places, now);
  await deps.repo.upsertHotels(docs.hotels);
  await deps.repo.upsertVenues(docs.venues);
  return docs;
}

/**
 * Imports when nothing is stored yet or the last import is a day old.
 * The worker has no boot hook, so a frequent schedule plus this check
 * means the first run lands within minutes of boot and then daily.
 */
export async function refreshIfStale(deps: ImportDeps): Promise<StaysImport | null> {
  const now = deps.now ?? new Date();
  const last = await deps.repo.lastImportAt();
  if (last && now.getTime() - last.getTime() < REFRESH_INTERVAL_MS) return null;
  return importNewcastlePlaces({ ...deps, now });
}

export const jobs: Job[] = [
  {
    name: "stays.osm",
    schedule: "*/5 * * * *",
    run: async () => {
      const imported = await refreshIfStale({ repo: createStaysRepo() });
      if (imported) {
        console.log(
          `stays.osm stored ${imported.hotels.length} hotels and ${imported.venues.length} venues`,
        );
      }
    },
  },
];
import type { AnyBulkWriteOperation, Collection } from "mongodb";
import { mongo } from "../../db/mongo";

/** Mongo collections from docs/ARCHITECTURE.md. Both carry a 2dsphere index on `location`. */
export const HOTELS_COLLECTION = "hotels";
export const VENUES_COLLECTION = "venues";

export type GeoPoint = { type: "Point"; coordinates: [number, number] };

/** Never a real booking. Revenue is shown as the model (docs/DECISIONS.md). */
export type PlaceholderBookingLink = {
  url: string;
  placeholder: true;
  label: string;
};

type OsmFields = {
  /** OSM id, `node/123`, `way/123` or `relation/123`. */
  _id: string;
  name: string | null;
  location: GeoPoint;
  /** The OSM tourism or amenity value, e.g. `hotel`, `pub`, `museum`. */
  category: string;
  tags: Record<string, string>;
  updatedAt: Date;
};

export type HotelDocument = OsmFields & { bookingLink: PlaceholderBookingLink };
export type VenueDocument = OsmFields & { venueKind: "nightlife" | "sight" };

export type StaysRepo = {
  /** Upserts by OSM id. Fields other features add to a document are left alone. */
  upsertHotels(hotels: HotelDocument[]): Promise<void>;
  upsertVenues(venues: VenueDocument[]): Promise<void>;
  /** Newest `updatedAt` across hotels and venues, or null when both are empty. */
  lastImportAt(): Promise<Date | null>;
};

function upsertOps<T extends OsmFields>(docs: readonly T[]): AnyBulkWriteOperation<T>[] {
  return docs.map((doc) => {
    const { _id, ...fields } = doc;
    return {
      updateOne: {
        filter: { _id } as never,
        update: { $set: fields } as never,
        upsert: true,
      },
    };
  });
}

async function newest(collection: Collection<OsmFields>): Promise<Date | null> {
  const doc = await collection.find({}).sort({ updatedAt: -1 }).limit(1).next();
  return doc?.updatedAt ?? null;
}

export function createStaysRepo(): StaysRepo {
  const db = mongo();
  const hotels = db.collection<HotelDocument>(HOTELS_COLLECTION);
  const venues = db.collection<VenueDocument>(VENUES_COLLECTION);

  return {
    async upsertHotels(docs) {
      if (docs.length > 0) await hotels.bulkWrite(upsertOps(docs));
    },
    async upsertVenues(docs) {
      if (docs.length > 0) await venues.bulkWrite(upsertOps(docs));
    },
    async lastImportAt() {
      const [a, b] = await Promise.all([
        newest(hotels as unknown as Collection<OsmFields>),
        newest(venues as unknown as Collection<OsmFields>),
      ]);
      if (!a || !b) return a ?? b;
      return a > b ? a : b;
    },
  };
}
